source=(extract/'main.py').read_text(encoding='utf-8')

def fresh_last_callable(cwd):
    old_cwd=Path.cwd()
    if str(extract) not in sys.path: sys.path.insert(0,str(extract))
    try:
        os.chdir(cwd)
        namespace={'__name__':'__ptcg_fresh_probe__','__builtins__':__builtins__}
        exec(compile(source,'main.py','exec'),namespace)
    finally:
        os.chdir(old_cwd)
    callables=[(name,value) for name,value in namespace.items() if not name.startswith('__') and callable(value)]
    assert callables
    selected_name,selected=callables[-1]
    required=[p for p in inspect.signature(selected).parameters.values() if p.default is inspect.Parameter.empty and p.kind in (p.POSITIONAL_ONLY,p.POSITIONAL_OR_KEYWORD)]
    assert selected_name==EXPECTED_FINAL_CALLABLE and len(required)==1 and '__file__' not in namespace
    return selected_name,selected,[name for name,_ in callables]

cwd_probes=[('extract',extract),('working',WORK),('visuals',VIS)]
startup_inputs=[('empty',{}),('null_select',{'current':None,'select':None}),('none',None)]
probe_rows=[]
for cwd_label,cwd in cwd_probes:
    for observation_label,observation in startup_inputs:
        selected_name,selected,callable_names=fresh_last_callable(cwd)
        returned=selected(observation)
        row={'cwd':cwd_label,'observation':observation_label,'selected':selected_name,'callable_tail':callable_names[-2:],
             'returned_length':len(returned) if isinstance(returned,list) else None,
             'exact_ordered_deck':returned==deck_ids,'namespace_omits_file':True}
        probe_rows.append(row)
assert len(probe_rows)==9 and all(row['returned_length']==60 and row['exact_ordered_deck'] for row in probe_rows)

from cg.api import to_observation_class
from cg.game import battle_finish,battle_select,battle_start
self_games=[]
for game_index in range(4):
    _,player0,_=fresh_last_callable(extract)
    _,player1,_=fresh_last_callable(extract)
    observation,started=battle_start(deck_ids,deck_ids)
    if observation is None: raise RuntimeError(f'battle_start failed: {started}')
    winner=None
    try:
        for step in range(1200):
            state=to_observation_class(observation).current
            if state.result >= 0:
                winner=int(state.result); break
            selected=player0 if state.yourIndex==0 else player1
            choices=selected(observation)
            legal=observation['select']
            assert isinstance(choices,list) and all(type(index) is int for index in choices)
            assert int(legal['minCount']) <= len(choices) <= int(legal['maxCount'])
            assert all(0 <= index < len(legal['option']) for index in choices)
            observation=battle_select(choices)
        else:
            raise TimeoutError('official-engine self-game exceeded 1,200 legal selections')
    finally:
        battle_finish()
    self_games.append({'game_index':game_index,'winner':winner,'steps':step,'error':None})

